-- ============================================================
--  Experiencias de clase: Curso de Gestión de Desviaciones y Acciones Correctivas y Preventivas — CAPA
--
--  Generado por scripts/generar-experiencias-catalogo.mjs a partir del
--  resumen de cada clase, los enlaces verificados y el material de
--  evaluación de contenido/aula/catalogo. No editar a mano.
--
--  35 clases. No toca cursos con experiencia escrita a
--  mano ni clases que ya tenían texto largo aprobado.
-- ============================================================

DO $curso$
DECLARE
  v_curso BIGINT;
  v_clase BIGINT;
  v_data  JSONB;
  v_n     INTEGER := 0;
BEGIN
  SELECT id INTO v_curso FROM aula_courses
   WHERE kind = 'edvanta' AND title = $t$Curso de Gestión de Desviaciones y Acciones Correctivas y Preventivas — CAPA$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_curso IS NULL THEN
    RAISE NOTICE 'Experiencias: no existe el curso %. Se salta.', $t$Curso de Gestión de Desviaciones y Acciones Correctivas y Preventivas — CAPA$t$;
    RETURN;
  END IF;

  -- 01. Introducción al curso: por qué las desviaciones y el CAPA son el corazón del sistema de calidad
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Introducción al curso: por qué las desviaciones y el CAPA son el corazón del sistema de calidad$t$
     AND m.title = $u$Unidad 1. Fundamentos de las desviaciones y marco regulatorio$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Introducción al curso: por qué las desviaciones y el CAPA son el corazón del sistema de calidad$t$, $u$Unidad 1. Fundamentos de las desviaciones y marco regulatorio$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Introducción al curso: por qué las desviaciones y el CAPA son el corazón del sistema de calidad","texto":"En una planta o un laboratorio farmacéutico colombiano, un proveedor cambia de planta y el certificado que llega no cubre la línea que fabrica el insumo. Lo que está en juego es el criterio de introducción al curso: por qué las desviaciones y el CAPA son el corazón del sistema de calidad. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar introducción al curso: por qué las desviaciones y el CAPA son el corazón del sistema de calidad con tus propias palabras y reconocer por qué importa en curso de Gestión de Desviaciones y Acciones Correctivas y Preventivas — CAPA.","Relacionar introducción al curso: por qué las desviaciones y el CAPA son el corazón del sistema de calidad con unidad 1. Fundamentos de las desviaciones y marco regulatorio y con las decisiones de el químico farmacéutico de aseguramiento o control de calidad.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar introducción al curso: por qué las desviaciones y el CAPA son el corazón del sistema de calidad y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Resume el alcance del curso, el ciclo desviación–investigación–CAPA–efectividad y su papel dentro del sistema de calidad farmacéutico exigido por el INVIMA."},{"icono":"ShieldCheck","termino":"Requisito","definicion":"Lo que la norma, el registro sanitario o el procedimiento exigen antes de aceptar una decisión. No es una recomendación: es el criterio contra el que se compara la evidencia."},{"icono":"FileCheck","termino":"Evidencia documentada","definicion":"El registro que permite reconstruir qué se hizo, quién lo hizo, cuándo y con qué resultado. Sin evidencia, una actividad existe solo en la memoria de quien la ejecutó."},{"icono":"Network","termino":"Trazabilidad","definicion":"La capacidad de seguir un lote, una muestra o una decisión desde su origen hasta su disposición final. Es lo que permite investigar y responder ante una autoridad."},{"icono":"ClipboardCheck","termino":"Criterio de aceptación","definicion":"El límite definido antes de ejecutar una prueba o una revisión. Si el criterio se fija después de ver el resultado, la decisión pierde valor."},{"icono":"RefreshCw","termino":"Desviación","definicion":"Cualquier apartamiento de lo previsto en un procedimiento, una especificación o una norma. No es solo un error: es una señal que debe evaluarse."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En una planta o un laboratorio farmacéutico colombiano, introducción al curso: por qué las desviaciones y el CAPA son el corazón del sistema de calidad aparece en medio de una decisión que no admite improvisación: un proveedor cambia de planta y el certificado que llega no cubre la línea que fabrica el insumo. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 1. Fundamentos de las desviaciones y marco regulatorio. El objetivo del curso es claro: Que el Químico Farmacéutico sea capaz de detectar, clasificar, contener e investigar desviaciones, resultados OOS y quejas, y de diseñar, implementar y verificar la efectividad de acciones CAPA conforme a la normativa colombiana y los referentes internacionales. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Resume el alcance del curso, el ciclo desviación–investigación–CAPA–efectividad y su papel dentro del sistema de calidad farmacéutico exigido por el INVIMA.","Para estudiar esta clase, convierte el título en una pregunta operativa: ¿qué debe estar claro antes de actuar y qué debe quedar registrado después? La respuesta se apoya en requisito y en evidencia documentada, no en la intuición.","La clase pertenece a unidad 1. Fundamentos de las desviaciones y marco regulatorio y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Matriz de clasificación de eventos con su gestión.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar introducción al curso: por qué las desviaciones y el CAPA son el corazón del sistema de calidad, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y escribe una definición operativa de cada tipo de evento. Evidencia que debe quedar: Registro del paso.","Clasifica los diez eventos por tipo (desviación planeada o no planeada, OOS, OOT, queja, no conformidad de auditoría o cambio). Evidencia que debe quedar: Registro del paso.","Asigna a las desviaciones una criticidad (crítica, mayor o menor) con un criterio de riesgo explícito. Evidencia que debe quedar: Registro del paso.","Indica para cada evento el proceso que lo gestiona y la investigación que exige. Evidencia que debe quedar: Registro del paso.","Señala qué eventos podrían estar relacionados entre sí y por qué. Evidencia que debe quedar: Registro del paso.","Cita la norma o guía que respalda cada decisión. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: confundir el análisis final con la garantía de calidad Corrección: el muestreo no detecta todos los defectos; la calidad se construye durante el proceso.","Error: cerrar una CAPA sin verificar eficacia Corrección: una acción correctiva se cierra cuando se demuestra que el problema no volvió, no cuando se firma el formato.","Error: tratar todos los riesgos como iguales Corrección: priorizar permite dirigir el esfuerzo a lo que más puede afectar al paciente y al producto.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar introducción al curso: por qué las desviaciones y el CAPA son el corazón del sistema de calidad en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"]}],"errores":[{"error":"Documentar después de ejecutar","correccion":"El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."},{"error":"Copiar un procedimiento de otra planta","correccion":"El procedimiento debe responder a los equipos, las áreas y los riesgos reales del proceso."},{"error":"Cerrar una CAPA sin verificar eficacia","correccion":"Una acción correctiva se cierra cuando se demuestra que el problema no volvió, no cuando se firma el formato."},{"error":"Tratar todos los riesgos como iguales","correccion":"Priorizar permite dirigir el esfuerzo a lo que más puede afectar al paciente y al producto."},{"error":"Confundir el análisis final con la garantía de calidad","correccion":"El muestreo no detecta todos los defectos; la calidad se construye durante el proceso."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Introducción al curso: por qué las desviaciones y el CAPA son el corazón del sistema de calidad»?","respuesta":"Resume el alcance del curso, el ciclo desviación–investigación–CAPA–efectividad y su papel dentro del sistema de calidad farmacéutico exigido por el INVIMA."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Matriz de clasificación de eventos con su gestión.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Documentar después de ejecutar El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."}],"resumen":["Introducción al curso: por qué las desviaciones y el CAPA son el corazón del sistema de calidad se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 1. Fundamentos de las desviaciones y marco regulatorio.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"],"referencias":[{"cita":"CAPAs, acciones correctivas y preventivas","url":"https://www.youtube.com/watch?v=JeLh8LTbH5E"},{"cita":"ICH Q10 Pharmaceutical Quality System (sección 3.2.2 Sistema CAPA). ICH (EN)","url":"https://database.ich.org/sites/default/files/Q10%20Guideline.pdf"},{"cita":"Resolución 1160 de 2016 – Manuales de Buenas Prácticas de Manufactura y guías de inspección. Ministerio de Salud y Protección Social de Colombia (ES)","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"},{"cita":"PIC/S. PE 009, Guide to Good Manufacturing Practice for Medicinal Products, Part I.","url":"https://picscheme.org/docview/4590"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente introducción al curso: por qué las desviaciones y el CAPA son el corazón del sistema de calidad en una planta o un laboratorio farmacéutico colombiano.","alt":"Ilustración de introducción al curso: por qué las desviaciones y el CAPA son el corazón del sistema de calidad"}],"keywords":["curso","gestión","desviaciones","acciones","correctivas","preventivas","introducción","corazón","sistema","calidad","unidad","fundamentos"],"mapa":{"centro":"Introducción al curso: por qué las desviaciones y el CAPA son el corazón del sistema de calidad","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Calidad farmacéutica","Unidad 1. Fundamentos de las desviaciones y marco regulatorio","Requisito"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Documentar después de ejecutar","Copiar un procedimiento de otra planta","Cerrar una CAPA sin verificar eficacia"]}]},"proceso":{"titulo":"Cómo se aplica: Clasificación de diez eventos de calidad","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y escribe una definición operativa de cada tipo de evento.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Clasifica los diez eventos por tipo (desviación planeada o no planeada, OOS, OOT, queja, no conformidad de auditoría o cambio).","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Asigna a las desviaciones una criticidad (crítica, mayor o menor) con un criterio de riesgo explícito.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Indica para cada evento el proceso que lo gestiona y la investigación que exige.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Señala qué eventos podrían estar relacionados entre sí y por qué.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Cita la norma o guía que respalda cada decisión.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Clasificación de diez eventos de calidad","contexto":"En una semana, Laboratorios Magdalena Medio (ficticio) registró diez eventos (datos simulados): (1) temperatura de una bodega a 28 °C durante 4 horas (límite 25 °C); (2) una valoración de 93 % (especificación 95–105 %); (3) un cliente que encontró una tableta partida; (4) uso planificado de un granulador alterno durante un mantenimiento; (5) un hallazgo de auditoría interna sobre registros incompletos; (6) un aumento de la impureza A en estabilidad, aún dentro de especificación; (7) un cambio de proveedor de cajas aprobado en control de cambios; (8) una etiqueta con el número de lote ilegible en 50 unidades segregadas en línea; (9) un filtro de venteo de un tanque de agua purificada vencido; (10) un operario que entró al área sin cofia.","pregunta":"¿Qué decisión demuestra que entendiste introducción al curso: por qué las desviaciones y el CAPA son el corazón del sistema de calidad?","opciones":[{"texto":"Verificar el requisito, aplicar el criterio de la clase y documentar la evidencia antes de decidir.","correcta":true,"retro":"La decisión profesional se apoya en el requisito, la evidencia y el registro. Sin esos tres elementos no se puede defender."},{"texto":"Resolver por costumbre o por presión de tiempo, sin revisar la evidencia.","correcta":false,"retro":"La costumbre no reemplaza el criterio. Si no hay evidencia, la decisión queda expuesta."},{"texto":"Trasladar la decisión a otra área sin dejar registro ni seguimiento.","correcta":false,"retro":"Trasladar no es delegar con control: sin registro y seguimiento, el problema vuelve."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 02. Desviación, no conformidad, OOS y queja: definiciones y diferencias
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Desviación, no conformidad, OOS y queja: definiciones y diferencias$t$
     AND m.title = $u$Unidad 1. Fundamentos de las desviaciones y marco regulatorio$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Desviación, no conformidad, OOS y queja: definiciones y diferencias$t$, $u$Unidad 1. Fundamentos de las desviaciones y marco regulatorio$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Desviación, no conformidad, OOS y queja: definiciones y diferencias","texto":"En una planta o un laboratorio farmacéutico colombiano, un proveedor cambia de planta y el certificado que llega no cubre la línea que fabrica el insumo. Lo que está en juego es el criterio de desviación, no conformidad, OOS y queja: definiciones y diferencias. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar desviación, no conformidad, OOS y queja: definiciones y diferencias con tus propias palabras y reconocer por qué importa en curso de Gestión de Desviaciones y Acciones Correctivas y Preventivas — CAPA.","Relacionar desviación, no conformidad, OOS y queja: definiciones y diferencias con unidad 1. Fundamentos de las desviaciones y marco regulatorio y con las decisiones de el químico farmacéutico de aseguramiento o control de calidad.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar desviación, no conformidad, OOS y queja: definiciones y diferencias y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Describe qué es una desviación y cómo se diferencia de una no conformidad, un resultado OOS, una queja y un defecto de calidad."},{"icono":"ShieldCheck","termino":"Requisito","definicion":"Lo que la norma, el registro sanitario o el procedimiento exigen antes de aceptar una decisión. No es una recomendación: es el criterio contra el que se compara la evidencia."},{"icono":"FileCheck","termino":"Evidencia documentada","definicion":"El registro que permite reconstruir qué se hizo, quién lo hizo, cuándo y con qué resultado. Sin evidencia, una actividad existe solo en la memoria de quien la ejecutó."},{"icono":"Network","termino":"Trazabilidad","definicion":"La capacidad de seguir un lote, una muestra o una decisión desde su origen hasta su disposición final. Es lo que permite investigar y responder ante una autoridad."},{"icono":"ClipboardCheck","termino":"Criterio de aceptación","definicion":"El límite definido antes de ejecutar una prueba o una revisión. Si el criterio se fija después de ver el resultado, la decisión pierde valor."},{"icono":"RefreshCw","termino":"Desviación","definicion":"Cualquier apartamiento de lo previsto en un procedimiento, una especificación o una norma. No es solo un error: es una señal que debe evaluarse."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En una planta o un laboratorio farmacéutico colombiano, desviación, no conformidad, OOS y queja: definiciones y diferencias aparece en medio de una decisión que no admite improvisación: un proveedor cambia de planta y el certificado que llega no cubre la línea que fabrica el insumo. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 1. Fundamentos de las desviaciones y marco regulatorio. El objetivo del curso es claro: Que el Químico Farmacéutico sea capaz de detectar, clasificar, contener e investigar desviaciones, resultados OOS y quejas, y de diseñar, implementar y verificar la efectividad de acciones CAPA conforme a la normativa colombiana y los referentes internacionales. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Describe qué es una desviación y cómo se diferencia de una no conformidad, un resultado OOS, una queja y un defecto de calidad.","Una pregunta que se usa para comprobar esta clase es: «¿Qué es una desviación en el contexto de las BPM?» La respuesta correcta se apoya en lo siguiente: Una desviación es un apartamiento de una instrucción aprobada o de un estándar establecido (procedimiento, registro de lote, especificación de proceso). Se distingue de un resultado OOS, de una queja y de un cambio, aunque pueden relacionarse. La fuente citada es: Resolución 1160 de 2016; ICH Q10; OMS TRS 986, anexo 2.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 1. Fundamentos de las desviaciones y marco regulatorio y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Matriz de clasificación de eventos con su gestión.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar desviación, no conformidad, OOS y queja: definiciones y diferencias, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y escribe una definición operativa de cada tipo de evento. Evidencia que debe quedar: Registro del paso.","Clasifica los diez eventos por tipo (desviación planeada o no planeada, OOS, OOT, queja, no conformidad de auditoría o cambio). Evidencia que debe quedar: Registro del paso.","Asigna a las desviaciones una criticidad (crítica, mayor o menor) con un criterio de riesgo explícito. Evidencia que debe quedar: Registro del paso.","Indica para cada evento el proceso que lo gestiona y la investigación que exige. Evidencia que debe quedar: Registro del paso.","Señala qué eventos podrían estar relacionados entre sí y por qué. Evidencia que debe quedar: Registro del paso.","Cita la norma o guía que respalda cada decisión. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil.","La discusión de la unidad añade otra capa: En una planta ficticia, los supervisores discuten tres eventos (datos simulados): una pesada que se repitió porque el operario derramó un poco de polvo, con el nuevo peso registrado; un control de dureza fuera de rango que se corrigió ajustando la máquina en el momento; y un retraso de un día en la limpieza de un tanque que no se usó en ese periodo. Unos quieren registrar todo como desviación y otros «solo lo grave». No se trata de opinar: se trata de sostener una postura con una fuente y con los datos del caso."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: cerrar una CAPA sin verificar eficacia Corrección: una acción correctiva se cierra cuando se demuestra que el problema no volvió, no cuando se firma el formato.","Error: tratar todos los riesgos como iguales Corrección: priorizar permite dirigir el esfuerzo a lo que más puede afectar al paciente y al producto.","Error: confundir el análisis final con la garantía de calidad Corrección: el muestreo no detecta todos los defectos; la calidad se construye durante el proceso.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar desviación, no conformidad, OOS y queja: definiciones y diferencias en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"]}],"errores":[{"error":"Documentar después de ejecutar","correccion":"El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."},{"error":"Copiar un procedimiento de otra planta","correccion":"El procedimiento debe responder a los equipos, las áreas y los riesgos reales del proceso."},{"error":"Cerrar una CAPA sin verificar eficacia","correccion":"Una acción correctiva se cierra cuando se demuestra que el problema no volvió, no cuando se firma el formato."},{"error":"Tratar todos los riesgos como iguales","correccion":"Priorizar permite dirigir el esfuerzo a lo que más puede afectar al paciente y al producto."},{"error":"Confundir el análisis final con la garantía de calidad","correccion":"El muestreo no detecta todos los defectos; la calidad se construye durante el proceso."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Desviación, no conformidad, OOS y queja: definiciones y diferencias»?","respuesta":"Describe qué es una desviación y cómo se diferencia de una no conformidad, un resultado OOS, una queja y un defecto de calidad."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Matriz de clasificación de eventos con su gestión.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Documentar después de ejecutar El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."}],"resumen":["Desviación, no conformidad, OOS y queja: definiciones y diferencias se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 1. Fundamentos de las desviaciones y marco regulatorio.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"],"referencias":[{"cita":"Desviaciones","url":"https://www.youtube.com/watch?v=UMXpQKJ5YY0"},{"cita":"EudraLex Vol. 4 – Capítulo 1: Pharmaceutical Quality System (desviaciones y CAPA, 1.4 xiv). Comisión Europea (EN)","url":"https://health.ec.europa.eu/system/files/2016-11/vol4-chap1_2013-01_en_0.pdf"},{"cita":"Resolución 1160 de 2016 – Manuales de Buenas Prácticas de Manufactura y guías de inspección. Ministerio de Salud y Protección Social de Colombia (ES)","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"},{"cita":"ICH. Q10: Pharmaceutical Quality System.","url":"https://database.ich.org/sites/default/files/Q10%20Guideline.pdf"},{"cita":"PIC/S. PE 009, Guide to Good Manufacturing Practice for Medicinal Products, Part I.","url":"https://picscheme.org/docview/4590"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente desviación, no conformidad, OOS y queja: definiciones y diferencias en una planta o un laboratorio farmacéutico colombiano.","alt":"Ilustración de desviación, no conformidad, OOS y queja: definiciones y diferencias"}],"keywords":["curso","gestión","desviaciones","acciones","correctivas","preventivas","desviación","conformidad","queja","definiciones","diferencias","unidad"],"mapa":{"centro":"Desviación, no conformidad, OOS y queja: definiciones y diferencias","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Calidad farmacéutica","Unidad 1. Fundamentos de las desviaciones y marco regulatorio","Requisito"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Documentar después de ejecutar","Copiar un procedimiento de otra planta","Cerrar una CAPA sin verificar eficacia"]}]},"proceso":{"titulo":"Cómo se aplica: Clasificación de diez eventos de calidad","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y escribe una definición operativa de cada tipo de evento.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Clasifica los diez eventos por tipo (desviación planeada o no planeada, OOS, OOT, queja, no conformidad de auditoría o cambio).","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Asigna a las desviaciones una criticidad (crítica, mayor o menor) con un criterio de riesgo explícito.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Indica para cada evento el proceso que lo gestiona y la investigación que exige.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Señala qué eventos podrían estar relacionados entre sí y por qué.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Cita la norma o guía que respalda cada decisión.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Desviación, no conformidad, OOS y queja: definiciones y diferencias","contexto":"En una planta o un laboratorio farmacéutico colombiano, el equipo analiza este caso de unidad 1. Fundamentos de las desviaciones y marco regulatorio: En una semana, Laboratorios Magdalena Medio (ficticio) registró diez eventos (datos simulados): (1) temperatura de una bodega a 28 °C durante 4 horas (límite 25 °C); (2) una valoración de 93 % (especificación 95–105 %); (3) un cliente que encontró una tableta partida; (4) uso planificado de un granulador alterno durante un mantenimiento; (5) un hallazgo de auditoría interna sobre registros incompletos; (6) un aumento de la impureza A en estabilidad, aún dentro de especificación; (7) un cambio de proveedor de cajas aprobado en control de cambios; (8) una etiqueta con el número de lote ilegible en 50 unidades segregadas en línea; (9) un filtro de venteo de un tanque de agua purificada vencido; (10) un operario que entró al área sin cofia. La pregunta que decide esta clase es: ¿Qué es una desviación en el contexto de las BPM?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Cualquier queja que presenta un cliente sobre el precio o la entrega del producto que compró.","correcta":false,"retro":"Una queja comercial no es una desviación de BPM."},{"texto":"Un resultado de laboratorio que cumple la especificación, pero es distinto del resultado anterior.","correcta":false,"retro":"Eso puede ser un resultado fuera de tendencia, no necesariamente una desviación."},{"texto":"Un cambio planificado y aprobado en el control de cambios antes de su implementación.","correcta":false,"retro":"Un cambio aprobado no es una desviación."},{"texto":"Un apartamiento de una instrucción aprobada, un procedimiento o un estándar establecido.","correcta":true,"retro":"Correcto. Puede ser planeada o no planeada."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 03. Desviaciones planeadas y no planeadas
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Desviaciones planeadas y no planeadas$t$
     AND m.title = $u$Unidad 1. Fundamentos de las desviaciones y marco regulatorio$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Desviaciones planeadas y no planeadas$t$, $u$Unidad 1. Fundamentos de las desviaciones y marco regulatorio$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Desviaciones planeadas y no planeadas","texto":"En una planta o un laboratorio farmacéutico colombiano, un proveedor cambia de planta y el certificado que llega no cubre la línea que fabrica el insumo. Lo que está en juego es el criterio de desviaciones planeadas y no planeadas. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar desviaciones planeadas y no planeadas con tus propias palabras y reconocer por qué importa en curso de Gestión de Desviaciones y Acciones Correctivas y Preventivas — CAPA.","Relacionar desviaciones planeadas y no planeadas con unidad 1. Fundamentos de las desviaciones y marco regulatorio y con las decisiones de el químico farmacéutico de aseguramiento o control de calidad.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar desviaciones planeadas y no planeadas y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Diferencia las desviaciones planeadas de las no planeadas, sus requisitos de aprobación y su relación con el control de cambios. diferenciar una desviación planeada de una no planeada y saber cuándo cada una es aceptable dentro de un sistema de calidad conforme a la Resolución 1160 de 2016. una desviación es cualquier apartamiento de una instrucción aprobada (procedimiento, orden de producción, especificación, método analítico, condición ambiental o de equipo).…"},{"icono":"ShieldCheck","termino":"Requisito","definicion":"Lo que la norma, el registro sanitario o el procedimiento exigen antes de aceptar una decisión. No es una recomendación: es el criterio contra el que se compara la evidencia."},{"icono":"FileCheck","termino":"Evidencia documentada","definicion":"El registro que permite reconstruir qué se hizo, quién lo hizo, cuándo y con qué resultado. Sin evidencia, una actividad existe solo en la memoria de quien la ejecutó."},{"icono":"Network","termino":"Trazabilidad","definicion":"La capacidad de seguir un lote, una muestra o una decisión desde su origen hasta su disposición final. Es lo que permite investigar y responder ante una autoridad."},{"icono":"ClipboardCheck","termino":"Criterio de aceptación","definicion":"El límite definido antes de ejecutar una prueba o una revisión. Si el criterio se fija después de ver el resultado, la decisión pierde valor."},{"icono":"RefreshCw","termino":"Desviación","definicion":"Cualquier apartamiento de lo previsto en un procedimiento, una especificación o una norma. No es solo un error: es una señal que debe evaluarse."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En una planta o un laboratorio farmacéutico colombiano, desviaciones planeadas y no planeadas aparece en medio de una decisión que no admite improvisación: un proveedor cambia de planta y el certificado que llega no cubre la línea que fabrica el insumo. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 1. Fundamentos de las desviaciones y marco regulatorio. El objetivo del curso es claro: Que el Químico Farmacéutico sea capaz de detectar, clasificar, contener e investigar desviaciones, resultados OOS y quejas, y de diseñar, implementar y verificar la efectividad de acciones CAPA conforme a la normativa colombiana y los referentes internacionales. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Diferencia las desviaciones planeadas de las no planeadas, sus requisitos de aprobación y su relación con el control de cambios. diferenciar una desviación planeada de una no planeada y saber cuándo cada una es aceptable dentro de un sistema de calidad conforme a la Resolución 1160 de 2016. una desviación es cualquier apartamiento de una instrucción aprobada (procedimiento, orden de producción, especificación, método analítico, condición ambiental o de equipo).…","Una pregunta que se usa para comprobar esta clase es: «Por un daño en la tableteadora habitual, producción quiere fabricar un lote en otra tableteadora del mismo modelo, calificada, que no figura en el registro de lote. ¿Cómo se gestiona?» La respuesta correcta se apoya en lo siguiente: Una desviación planeada es un apartamiento temporal y conocido de antemano que se evalúa (riesgo, impacto) y se aprueba antes de ejecutarse. Si el cambio va a ser permanente, se gestiona por control de cambios. La fuente citada es: Resolución 1160 de 2016; ICH Q10, gestión del cambio.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 1. Fundamentos de las desviaciones y marco regulatorio y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Matriz de clasificación de eventos con su gestión.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar desviaciones planeadas y no planeadas, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y escribe una definición operativa de cada tipo de evento. Evidencia que debe quedar: Registro del paso.","Clasifica los diez eventos por tipo (desviación planeada o no planeada, OOS, OOT, queja, no conformidad de auditoría o cambio). Evidencia que debe quedar: Registro del paso.","Asigna a las desviaciones una criticidad (crítica, mayor o menor) con un criterio de riesgo explícito. Evidencia que debe quedar: Registro del paso.","Indica para cada evento el proceso que lo gestiona y la investigación que exige. Evidencia que debe quedar: Registro del paso.","Señala qué eventos podrían estar relacionados entre sí y por qué. Evidencia que debe quedar: Registro del paso.","Cita la norma o guía que respalda cada decisión. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: cerrar una CAPA sin verificar eficacia Corrección: una acción correctiva se cierra cuando se demuestra que el problema no volvió, no cuando se firma el formato.","Error: tratar todos los riesgos como iguales Corrección: priorizar permite dirigir el esfuerzo a lo que más puede afectar al paciente y al producto.","Error: copiar un procedimiento de otra planta Corrección: el procedimiento debe responder a los equipos, las áreas y los riesgos reales del proceso.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar desviaciones planeadas y no planeadas en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"]}],"errores":[{"error":"Documentar después de ejecutar","correccion":"El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."},{"error":"Copiar un procedimiento de otra planta","correccion":"El procedimiento debe responder a los equipos, las áreas y los riesgos reales del proceso."},{"error":"Cerrar una CAPA sin verificar eficacia","correccion":"Una acción correctiva se cierra cuando se demuestra que el problema no volvió, no cuando se firma el formato."},{"error":"Tratar todos los riesgos como iguales","correccion":"Priorizar permite dirigir el esfuerzo a lo que más puede afectar al paciente y al producto."},{"error":"Confundir el análisis final con la garantía de calidad","correccion":"El muestreo no detecta todos los defectos; la calidad se construye durante el proceso."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Desviaciones planeadas y no planeadas»?","respuesta":"Diferencia las desviaciones planeadas de las no planeadas, sus requisitos de aprobación y su relación con el control de cambios. diferenciar una desviación planeada de una no planeada y saber cuándo cada una es aceptable dentro de un sistema de calidad conforme a la Resolución 1160 de 2016. una desviación es cualquier apartamiento de una instrucción aprobada (procedimiento, orden de producción, especificación, método analítico, condición ambiental o de equipo).…"},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Matriz de clasificación de eventos con su gestión.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Documentar después de ejecutar El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."}],"resumen":["Desviaciones planeadas y no planeadas se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 1. Fundamentos de las desviaciones y marco regulatorio.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"],"referencias":[{"cita":"Manejo de Desviaciones","url":"https://www.youtube.com/watch?v=ssFIvywjmZs"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016, manuales de BPM y autoinspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"},{"cita":"ICH. Q10: Pharmaceutical Quality System.","url":"https://database.ich.org/sites/default/files/Q10%20Guideline.pdf"},{"cita":"PIC/S. PE 009, Guide to Good Manufacturing Practice for Medicinal Products, Part I.","url":"https://picscheme.org/docview/4590"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente desviaciones planeadas y no planeadas en una planta o un laboratorio farmacéutico colombiano.","alt":"Ilustración de desviaciones planeadas y no planeadas"}],"keywords":["curso","gestión","desviaciones","acciones","correctivas","preventivas","planeadas","unidad","fundamentos","marco","regulatorio"],"mapa":{"centro":"Desviaciones planeadas y no planeadas","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Calidad farmacéutica","Unidad 1. Fundamentos de las desviaciones y marco regulatorio","Requisito"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Documentar después de ejecutar","Copiar un procedimiento de otra planta","Cerrar una CAPA sin verificar eficacia"]}]},"proceso":{"titulo":"Cómo se aplica: Clasificación de diez eventos de calidad","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y escribe una definición operativa de cada tipo de evento.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Clasifica los diez eventos por tipo (desviación planeada o no planeada, OOS, OOT, queja, no conformidad de auditoría o cambio).","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Asigna a las desviaciones una criticidad (crítica, mayor o menor) con un criterio de riesgo explícito.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Indica para cada evento el proceso que lo gestiona y la investigación que exige.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Señala qué eventos podrían estar relacionados entre sí y por qué.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Cita la norma o guía que respalda cada decisión.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Desviaciones planeadas y no planeadas","contexto":"En una planta o un laboratorio farmacéutico colombiano, el equipo analiza este caso de unidad 1. Fundamentos de las desviaciones y marco regulatorio: En una semana, Laboratorios Magdalena Medio (ficticio) registró diez eventos (datos simulados): (1) temperatura de una bodega a 28 °C durante 4 horas (límite 25 °C); (2) una valoración de 93 % (especificación 95–105 %); (3) un cliente que encontró una tableta partida; (4) uso planificado de un granulador alterno durante un mantenimiento; (5) un hallazgo de auditoría interna sobre registros incompletos; (6) un aumento de la impureza A en estabilidad, aún dentro de especificación; (7) un cambio de proveedor de cajas aprobado en control de cambios; (8) una etiqueta con el número de lote ilegible en 50 unidades segregadas en línea; (9) un filtro de venteo de un tanque de agua purificada vencido; (10) un operario que entró al área sin cofia. La pregunta que decide esta clase es: Por un daño en la tableteadora habitual, producción quiere fabricar un lote en otra tableteadora del mismo modelo, calificada, que no figura en el registro de lote. ¿Cómo se gestiona?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Se fabrica sin ningún registro adicional, porque ambos equipos son del mismo modelo y fabricante.","correcta":false,"retro":"Usar un equipo distinto del indicado es un apartamiento que debe evaluarse."},{"texto":"Como desviación planeada: se evalúa y se aprueba antes de ejecutarla, con su impacto documentado.","correcta":true,"retro":"Correcto. Si el uso fuera permanente, se tramitaría por control de cambios."},{"texto":"Se gestiona como una queja de calidad dirigida al proveedor de la tableteadora que se dañó.","correcta":false,"retro":"El daño del equipo no convierte esto en una queja."},{"texto":"Se fabrica y al final se abre una desviación no planeada, solo si algo llega a salir mal.","correcta":false,"retro":"Si se sabe de antemano, se evalúa y aprueba antes."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 04. Clasificación por criticidad: crítica, mayor y menor
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Clasificación por criticidad: crítica, mayor y menor$t$
     AND m.title = $u$Unidad 1. Fundamentos de las desviaciones y marco regulatorio$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Clasificación por criticidad: crítica, mayor y menor$t$, $u$Unidad 1. Fundamentos de las desviaciones y marco regulatorio$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Clasificación por criticidad: crítica, mayor y menor","texto":"En una planta o un laboratorio farmacéutico colombiano, un indicador empeora durante tres meses y nadie sabe explicar por qué. Lo que está en juego es el criterio de clasificación por criticidad: crítica, mayor y menor. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar clasificación por criticidad: crítica, mayor y menor con tus propias palabras y reconocer por qué importa en curso de Gestión de Desviaciones y Acciones Correctivas y Preventivas — CAPA.","Relacionar clasificación por criticidad: crítica, mayor y menor con unidad 1. Fundamentos de las desviaciones y marco regulatorio y con las decisiones de el químico farmacéutico de aseguramiento o control de calidad.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar clasificación por criticidad: crítica, mayor y menor y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Interpreta los criterios basados en riesgo para clasificar desviaciones como críticas, mayores o menores y su efecto en plazos y escalamiento."},{"icono":"ShieldCheck","termino":"Requisito","definicion":"Lo que la norma, el registro sanitario o el procedimiento exigen antes de aceptar una decisión. No es una recomendación: es el criterio contra el que se compara la evidencia."},{"icono":"FileCheck","termino":"Evidencia documentada","definicion":"El registro que permite reconstruir qué se hizo, quién lo hizo, cuándo y con qué resultado. Sin evidencia, una actividad existe solo en la memoria de quien la ejecutó."},{"icono":"Network","termino":"Trazabilidad","definicion":"La capacidad de seguir un lote, una muestra o una decisión desde su origen hasta su disposición final. Es lo que permite investigar y responder ante una autoridad."},{"icono":"ClipboardCheck","termino":"Criterio de aceptación","definicion":"El límite definido antes de ejecutar una prueba o una revisión. Si el criterio se fija después de ver el resultado, la decisión pierde valor."},{"icono":"RefreshCw","termino":"Desviación","definicion":"Cualquier apartamiento de lo previsto en un procedimiento, una especificación o una norma. No es solo un error: es una señal que debe evaluarse."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En una planta o un laboratorio farmacéutico colombiano, clasificación por criticidad: crítica, mayor y menor aparece en medio de una decisión que no admite improvisación: un indicador empeora durante tres meses y nadie sabe explicar por qué. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 1. Fundamentos de las desviaciones y marco regulatorio. El objetivo del curso es claro: Que el Químico Farmacéutico sea capaz de detectar, clasificar, contener e investigar desviaciones, resultados OOS y quejas, y de diseñar, implementar y verificar la efectividad de acciones CAPA conforme a la normativa colombiana y los referentes internacionales. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Interpreta los criterios basados en riesgo para clasificar desviaciones como críticas, mayores o menores y su efecto en plazos y escalamiento.","Una pregunta que se usa para comprobar esta clase es: «¿Cuál de estas desviaciones tiene mayor criticidad?» La respuesta correcta se apoya en lo siguiente: La criticidad se basa en el riesgo para la calidad y el paciente. Un filtro esterilizante que falla la integridad compromete la esterilidad de un inyectable: es una desviación crítica. La fuente citada es: ICH Q9(R1); Anexo 1 de las BPM de la UE (integridad de filtros).. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 1. Fundamentos de las desviaciones y marco regulatorio y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Matriz de clasificación de eventos con su gestión.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar clasificación por criticidad: crítica, mayor y menor, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y escribe una definición operativa de cada tipo de evento. Evidencia que debe quedar: Registro del paso.","Clasifica los diez eventos por tipo (desviación planeada o no planeada, OOS, OOT, queja, no conformidad de auditoría o cambio). Evidencia que debe quedar: Registro del paso.","Asigna a las desviaciones una criticidad (crítica, mayor o menor) con un criterio de riesgo explícito. Evidencia que debe quedar: Registro del paso.","Indica para cada evento el proceso que lo gestiona y la investigación que exige. Evidencia que debe quedar: Registro del paso.","Señala qué eventos podrían estar relacionados entre sí y por qué. Evidencia que debe quedar: Registro del paso.","Cita la norma o guía que respalda cada decisión. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil.","La discusión de la unidad añade otra capa: En una planta ficticia, los supervisores discuten tres eventos (datos simulados): una pesada que se repitió porque el operario derramó un poco de polvo, con el nuevo peso registrado; un control de dureza fuera de rango que se corrigió ajustando la máquina en el momento; y un retraso de un día en la limpieza de un tanque que no se usó en ese periodo. Unos quieren registrar todo como desviación y otros «solo lo grave». No se trata de opinar: se trata de sostener una postura con una fuente y con los datos del caso."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: copiar un procedimiento de otra planta Corrección: el procedimiento debe responder a los equipos, las áreas y los riesgos reales del proceso.","Error: confundir el análisis final con la garantía de calidad Corrección: el muestreo no detecta todos los defectos; la calidad se construye durante el proceso.","Error: documentar después de ejecutar Corrección: el registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar clasificación por criticidad: crítica, mayor y menor en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"]}],"errores":[{"error":"Documentar después de ejecutar","correccion":"El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."},{"error":"Copiar un procedimiento de otra planta","correccion":"El procedimiento debe responder a los equipos, las áreas y los riesgos reales del proceso."},{"error":"Cerrar una CAPA sin verificar eficacia","correccion":"Una acción correctiva se cierra cuando se demuestra que el problema no volvió, no cuando se firma el formato."},{"error":"Tratar todos los riesgos como iguales","correccion":"Priorizar permite dirigir el esfuerzo a lo que más puede afectar al paciente y al producto."},{"error":"Confundir el análisis final con la garantía de calidad","correccion":"El muestreo no detecta todos los defectos; la calidad se construye durante el proceso."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Clasificación por criticidad: crítica, mayor y menor»?","respuesta":"Interpreta los criterios basados en riesgo para clasificar desviaciones como críticas, mayores o menores y su efecto en plazos y escalamiento."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Matriz de clasificación de eventos con su gestión.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Documentar después de ejecutar El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."}],"resumen":["Clasificación por criticidad: crítica, mayor y menor se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 1. Fundamentos de las desviaciones y marco regulatorio.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"],"referencias":[{"cita":"ICH Q9(R1): Quality Risk Management","url":"https://www.youtube.com/watch?v=6twBwRyAZf4"},{"cita":"PIC/S PI 040-1 – Guidance on Classification of GMP Deficiencies. PIC/S (EN)","url":"https://picscheme.org/docview/2303"},{"cita":"ICH Q9(R1) Quality Risk Management (2023). ICH (EN)","url":"https://database.ich.org/sites/default/files/ICH_Q9%28R1%29_Guideline_Step4_2022_1219.pdf"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016, manuales de BPM y autoinspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"},{"cita":"ICH. Q10: Pharmaceutical Quality System.","url":"https://database.ich.org/sites/default/files/Q10%20Guideline.pdf"},{"cita":"PIC/S. PE 009, Guide to Good Manufacturing Practice for Medicinal Products, Part I.","url":"https://picscheme.org/docview/4590"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente clasificación por criticidad: crítica, mayor y menor en una planta o un laboratorio farmacéutico colombiano.","alt":"Ilustración de clasificación por criticidad: crítica, mayor y menor"}],"keywords":["curso","gestión","desviaciones","acciones","correctivas","preventivas","clasificación","criticidad","crítica","mayor","menor","unidad"],"mapa":{"centro":"Clasificación por criticidad: crítica, mayor y menor","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Calidad farmacéutica","Unidad 1. Fundamentos de las desviaciones y marco regulatorio","Requisito"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Documentar después de ejecutar","Copiar un procedimiento de otra planta","Cerrar una CAPA sin verificar eficacia"]}]},"proceso":{"titulo":"Cómo se aplica: Clasificación de diez eventos de calidad","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y escribe una definición operativa de cada tipo de evento.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Clasifica los diez eventos por tipo (desviación planeada o no planeada, OOS, OOT, queja, no conformidad de auditoría o cambio).","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Asigna a las desviaciones una criticidad (crítica, mayor o menor) con un criterio de riesgo explícito.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Indica para cada evento el proceso que lo gestiona y la investigación que exige.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Señala qué eventos podrían estar relacionados entre sí y por qué.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Cita la norma o guía que respalda cada decisión.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Clasificación por criticidad: crítica, mayor y menor","contexto":"En una planta o un laboratorio farmacéutico colombiano, el equipo analiza este caso de unidad 1. Fundamentos de las desviaciones y marco regulatorio: En una semana, Laboratorios Magdalena Medio (ficticio) registró diez eventos (datos simulados): (1) temperatura de una bodega a 28 °C durante 4 horas (límite 25 °C); (2) una valoración de 93 % (especificación 95–105 %); (3) un cliente que encontró una tableta partida; (4) uso planificado de un granulador alterno durante un mantenimiento; (5) un hallazgo de auditoría interna sobre registros incompletos; (6) un aumento de la impureza A en estabilidad, aún dentro de especificación; (7) un cambio de proveedor de cajas aprobado en control de cambios; (8) una etiqueta con el número de lote ilegible en 50 unidades segregadas en línea; (9) un filtro de venteo de un tanque de agua purificada vencido; (10) un operario que entró al área sin cofia. La pregunta que decide esta clase es: ¿Cuál de estas desviaciones tiene mayor criticidad?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Un lote inyectable filtrado con un filtro esterilizante cuya prueba de integridad posterior falló.","correcta":true,"retro":"Correcto. Pone en duda la esterilidad: riesgo directo y grave para el paciente."},{"texto":"Una firma faltante del verificador en un registro de limpieza, con evidencia indirecta de la limpieza.","correcta":false,"retro":"Es relevante, pero con evidencia indirecta su riesgo es menor."},{"texto":"Un retraso de dos horas en el inicio de la fabricación por la llegada tardía de un operario al turno.","correcta":false,"retro":"No tiene impacto directo en la calidad."},{"texto":"Una etiqueta de estado despegada en un contenedor de una materia prima que ya estaba aprobada.","correcta":false,"retro":"Debe corregirse, pero su riesgo es menor."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 05. Normativa colombiana: Resolución 1160 de 2016, Decreto 677 de 1995 e INVIMA
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Normativa colombiana: Resolución 1160 de 2016, Decreto 677 de 1995 e INVIMA$t$
     AND m.title = $u$Unidad 1. Fundamentos de las desviaciones y marco regulatorio$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Normativa colombiana: Resolución 1160 de 2016, Decreto 677 de 1995 e INVIMA$t$, $u$Unidad 1. Fundamentos de las desviaciones y marco regulatorio$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Normativa colombiana: Resolución 1160 de 2016, Decreto 677 de 1995 e INVIMA","texto":"En una planta o un laboratorio farmacéutico colombiano, un indicador empeora durante tres meses y nadie sabe explicar por qué. Lo que está en juego es el criterio de normativa colombiana: Resolución 1160 de 2016, Decreto 677 de 1995 e INVIMA. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar normativa colombiana: Resolución 1160 de 2016, Decreto 677 de 1995 e INVIMA con tus propias palabras y reconocer por qué importa en curso de Gestión de Desviaciones y Acciones Correctivas y Preventivas — CAPA.","Relacionar normativa colombiana: Resolución 1160 de 2016, Decreto 677 de 1995 e INVIMA con unidad 1. Fundamentos de las desviaciones y marco regulatorio y con las decisiones de el químico farmacéutico de aseguramiento o control de calidad.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar normativa colombiana: Resolución 1160 de 2016, Decreto 677 de 1995 e INVIMA y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Describe los requisitos de BPM colombianos sobre desviaciones, quejas, investigaciones y acciones correctivas, y el rol del INVIMA en su verificación."},{"icono":"ShieldCheck","termino":"Requisito","definicion":"Lo que la norma, el registro sanitario o el procedimiento exigen antes de aceptar una decisión. No es una recomendación: es el criterio contra el que se compara la evidencia."},{"icono":"FileCheck","termino":"Evidencia documentada","definicion":"El registro que permite reconstruir qué se hizo, quién lo hizo, cuándo y con qué resultado. Sin evidencia, una actividad existe solo en la memoria de quien la ejecutó."},{"icono":"Network","termino":"Trazabilidad","definicion":"La capacidad de seguir un lote, una muestra o una decisión desde su origen hasta su disposición final. Es lo que permite investigar y responder ante una autoridad."},{"icono":"ClipboardCheck","termino":"Criterio de aceptación","definicion":"El límite definido antes de ejecutar una prueba o una revisión. Si el criterio se fija después de ver el resultado, la decisión pierde valor."},{"icono":"RefreshCw","termino":"Desviación","definicion":"Cualquier apartamiento de lo previsto en un procedimiento, una especificación o una norma. No es solo un error: es una señal que debe evaluarse."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En una planta o un laboratorio farmacéutico colombiano, normativa colombiana: Resolución 1160 de 2016, Decreto 677 de 1995 e INVIMA aparece en medio de una decisión que no admite improvisación: un indicador empeora durante tres meses y nadie sabe explicar por qué. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 1. Fundamentos de las desviaciones y marco regulatorio. El objetivo del curso es claro: Que el Químico Farmacéutico sea capaz de detectar, clasificar, contener e investigar desviaciones, resultados OOS y quejas, y de diseñar, implementar y verificar la efectividad de acciones CAPA conforme a la normativa colombiana y los referentes internacionales. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Describe los requisitos de BPM colombianos sobre desviaciones, quejas, investigaciones y acciones correctivas, y el rol del INVIMA en su verificación.","Una pregunta que se usa para comprobar esta clase es: «Un laboratorio tiene un procedimiento de desviaciones, pero ninguna se investiga más allá de la descripción y todas se cierran con «se corrigió». ¿Cuál es la valoración más acertada frente a las BPM?» La respuesta correcta se apoya en lo siguiente: Las BPM exigen registrar, investigar las desviaciones significativas con la profundidad proporcional a su riesgo, documentar causas, acciones correctivas y preventivas, y evaluar su eficacia. La fuente citada es: Resolución 1160 de 2016; ICH Q10, sección 3.2.2.. No memorices la opción: reconstruye el razonamiento y verifica la fuente antes de usarla en un caso real.","La clase pertenece a unidad 1. Fundamentos de las desviaciones y marco regulatorio y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Matriz de clasificación de eventos con su gestión.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar normativa colombiana: Resolución 1160 de 2016, Decreto 677 de 1995 e INVIMA, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y escribe una definición operativa de cada tipo de evento. Evidencia que debe quedar: Registro del paso.","Clasifica los diez eventos por tipo (desviación planeada o no planeada, OOS, OOT, queja, no conformidad de auditoría o cambio). Evidencia que debe quedar: Registro del paso.","Asigna a las desviaciones una criticidad (crítica, mayor o menor) con un criterio de riesgo explícito. Evidencia que debe quedar: Registro del paso.","Indica para cada evento el proceso que lo gestiona y la investigación que exige. Evidencia que debe quedar: Registro del paso.","Señala qué eventos podrían estar relacionados entre sí y por qué. Evidencia que debe quedar: Registro del paso.","Cita la norma o guía que respalda cada decisión. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: documentar después de ejecutar Corrección: el registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad.","Error: copiar un procedimiento de otra planta Corrección: el procedimiento debe responder a los equipos, las áreas y los riesgos reales del proceso.","Error: tratar todos los riesgos como iguales Corrección: priorizar permite dirigir el esfuerzo a lo que más puede afectar al paciente y al producto.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar normativa colombiana: Resolución 1160 de 2016, Decreto 677 de 1995 e INVIMA en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"]}],"errores":[{"error":"Documentar después de ejecutar","correccion":"El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."},{"error":"Copiar un procedimiento de otra planta","correccion":"El procedimiento debe responder a los equipos, las áreas y los riesgos reales del proceso."},{"error":"Cerrar una CAPA sin verificar eficacia","correccion":"Una acción correctiva se cierra cuando se demuestra que el problema no volvió, no cuando se firma el formato."},{"error":"Tratar todos los riesgos como iguales","correccion":"Priorizar permite dirigir el esfuerzo a lo que más puede afectar al paciente y al producto."},{"error":"Confundir el análisis final con la garantía de calidad","correccion":"El muestreo no detecta todos los defectos; la calidad se construye durante el proceso."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Normativa colombiana: Resolución 1160 de 2016, Decreto 677 de 1995 e INVIMA»?","respuesta":"Describe los requisitos de BPM colombianos sobre desviaciones, quejas, investigaciones y acciones correctivas, y el rol del INVIMA en su verificación."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Matriz de clasificación de eventos con su gestión.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Documentar después de ejecutar El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."}],"resumen":["Normativa colombiana: Resolución 1160 de 2016, Decreto 677 de 1995 e INVIMA se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 1. Fundamentos de las desviaciones y marco regulatorio.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"],"referencias":[{"cita":"Buenas prácticas de manufactura (BPM) según INVIMA en Colombia, mayo 2020","url":"https://www.youtube.com/watch?v=w7H6ZO7mrCU"},{"cita":"Resolución 1160 de 2016 – Manuales de Buenas Prácticas de Manufactura y guías de inspección. Ministerio de Salud y Protección Social de Colombia (ES)","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"},{"cita":"Decreto 677 de 1995 – Régimen de registros, licencias, control de calidad y vigilancia sanitaria de medicamentos. Ministerio de Salud y Protección Social de Colombia (ES)","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/DECRETO%200677%20DE%201995.pdf"},{"cita":"ICH. Q10: Pharmaceutical Quality System.","url":"https://database.ich.org/sites/default/files/Q10%20Guideline.pdf"},{"cita":"PIC/S. PE 009, Guide to Good Manufacturing Practice for Medicinal Products, Part I.","url":"https://picscheme.org/docview/4590"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente normativa colombiana: Resolución 1160 de 2016, Decreto 677 de 1995 e INVIMA en una planta o un laboratorio farmacéutico colombiano.","alt":"Ilustración de normativa colombiana: Resolución 1160 de 2016, Decreto 677 de 1995 e INVIMA"}],"keywords":["curso","gestión","desviaciones","acciones","correctivas","preventivas","normativa","colombiana","resolución","decreto","invima","unidad"],"mapa":{"centro":"Normativa colombiana: Resolución 1160 de 2016, Decreto 677 de 1995 e INVIMA","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Calidad farmacéutica","Unidad 1. Fundamentos de las desviaciones y marco regulatorio","Requisito"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Documentar después de ejecutar","Copiar un procedimiento de otra planta","Cerrar una CAPA sin verificar eficacia"]}]},"proceso":{"titulo":"Cómo se aplica: Clasificación de diez eventos de calidad","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y escribe una definición operativa de cada tipo de evento.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Clasifica los diez eventos por tipo (desviación planeada o no planeada, OOS, OOT, queja, no conformidad de auditoría o cambio).","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Asigna a las desviaciones una criticidad (crítica, mayor o menor) con un criterio de riesgo explícito.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Indica para cada evento el proceso que lo gestiona y la investigación que exige.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Señala qué eventos podrían estar relacionados entre sí y por qué.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Cita la norma o guía que respalda cada decisión.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Normativa colombiana: Resolución 1160 de 2016, Decreto 677 de 1995 e INVIMA","contexto":"En una planta o un laboratorio farmacéutico colombiano, el equipo analiza este caso de unidad 1. Fundamentos de las desviaciones y marco regulatorio: En una semana, Laboratorios Magdalena Medio (ficticio) registró diez eventos (datos simulados): (1) temperatura de una bodega a 28 °C durante 4 horas (límite 25 °C); (2) una valoración de 93 % (especificación 95–105 %); (3) un cliente que encontró una tableta partida; (4) uso planificado de un granulador alterno durante un mantenimiento; (5) un hallazgo de auditoría interna sobre registros incompletos; (6) un aumento de la impureza A en estabilidad, aún dentro de especificación; (7) un cambio de proveedor de cajas aprobado en control de cambios; (8) una etiqueta con el número de lote ilegible en 50 unidades segregadas en línea; (9) un filtro de venteo de un tanque de agua purificada vencido; (10) un operario que entró al área sin cofia. La pregunta que decide esta clase es: Un laboratorio tiene un procedimiento de desviaciones, pero ninguna se investiga más allá de la descripción y todas se cierran con «se corrigió». ¿Cuál es la valoración más acertada frente a las BPM?","pregunta":"¿Cuál es la decisión profesional más sólida?","opciones":[{"texto":"Cumple, porque tener el procedimiento escrito es lo único que verifica el Invima en la visita.","correcta":false,"retro":"El Invima verifica también cómo se aplica el procedimiento."},{"texto":"Cumple si el número de desviaciones disminuye de un año a otro en el informe de la planta.","correcta":false,"retro":"Menos desviaciones registradas no prueba que se gestionen bien."},{"texto":"Incumple: se deben investigar, documentar causas y acciones y evaluar su eficacia.","correcta":true,"retro":"Correcto. Una corrección sin investigación no evita que se repita."},{"texto":"Incumple solo si alguna de las desviaciones terminó en un retiro de producto del mercado.","correcta":false,"retro":"La falla existe aunque no haya habido un retiro."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 06. Referentes internacionales: ICH Q10, OMS, PIC/S y EU GMP
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Referentes internacionales: ICH Q10, OMS, PIC/S y EU GMP$t$
     AND m.title = $u$Unidad 1. Fundamentos de las desviaciones y marco regulatorio$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Referentes internacionales: ICH Q10, OMS, PIC/S y EU GMP$t$, $u$Unidad 1. Fundamentos de las desviaciones y marco regulatorio$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Referentes internacionales: ICH Q10, OMS, PIC/S y EU GMP","texto":"En una planta o un laboratorio farmacéutico colombiano, un lote cumple las especificaciones, pero la revisión del expediente muestra una etapa sin verificar. Lo que está en juego es el criterio de referentes internacionales: ICH Q10, OMS, PIC/S y EU GMP. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar referentes internacionales: ICH Q10, OMS, PIC/S y EU GMP con tus propias palabras y reconocer por qué importa en curso de Gestión de Desviaciones y Acciones Correctivas y Preventivas — CAPA.","Relacionar referentes internacionales: ICH Q10, OMS, PIC/S y EU GMP con unidad 1. Fundamentos de las desviaciones y marco regulatorio y con las decisiones de el químico farmacéutico de aseguramiento o control de calidad.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar referentes internacionales: ICH Q10, OMS, PIC/S y EU GMP y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Compara cómo ICH Q10, el informe técnico de la OMS, la guía PIC/S y el Capítulo 1 de EU GMP tratan las desviaciones y el CAPA."},{"icono":"ShieldCheck","termino":"Requisito","definicion":"Lo que la norma, el registro sanitario o el procedimiento exigen antes de aceptar una decisión. No es una recomendación: es el criterio contra el que se compara la evidencia."},{"icono":"FileCheck","termino":"Evidencia documentada","definicion":"El registro que permite reconstruir qué se hizo, quién lo hizo, cuándo y con qué resultado. Sin evidencia, una actividad existe solo en la memoria de quien la ejecutó."},{"icono":"Network","termino":"Trazabilidad","definicion":"La capacidad de seguir un lote, una muestra o una decisión desde su origen hasta su disposición final. Es lo que permite investigar y responder ante una autoridad."},{"icono":"ClipboardCheck","termino":"Criterio de aceptación","definicion":"El límite definido antes de ejecutar una prueba o una revisión. Si el criterio se fija después de ver el resultado, la decisión pierde valor."},{"icono":"RefreshCw","termino":"Desviación","definicion":"Cualquier apartamiento de lo previsto en un procedimiento, una especificación o una norma. No es solo un error: es una señal que debe evaluarse."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En una planta o un laboratorio farmacéutico colombiano, referentes internacionales: ICH Q10, OMS, PIC/S y EU GMP aparece en medio de una decisión que no admite improvisación: un lote cumple las especificaciones, pero la revisión del expediente muestra una etapa sin verificar. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 1. Fundamentos de las desviaciones y marco regulatorio. El objetivo del curso es claro: Que el Químico Farmacéutico sea capaz de detectar, clasificar, contener e investigar desviaciones, resultados OOS y quejas, y de diseñar, implementar y verificar la efectividad de acciones CAPA conforme a la normativa colombiana y los referentes internacionales. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Compara cómo ICH Q10, el informe técnico de la OMS, la guía PIC/S y el Capítulo 1 de EU GMP tratan las desviaciones y el CAPA.","Para estudiar esta clase, convierte el título en una pregunta operativa: ¿qué debe estar claro antes de actuar y qué debe quedar registrado después? La respuesta se apoya en requisito y en evidencia documentada, no en la intuición.","La clase pertenece a unidad 1. Fundamentos de las desviaciones y marco regulatorio y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Matriz de clasificación de eventos con su gestión.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar referentes internacionales: ICH Q10, OMS, PIC/S y EU GMP, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y escribe una definición operativa de cada tipo de evento. Evidencia que debe quedar: Registro del paso.","Clasifica los diez eventos por tipo (desviación planeada o no planeada, OOS, OOT, queja, no conformidad de auditoría o cambio). Evidencia que debe quedar: Registro del paso.","Asigna a las desviaciones una criticidad (crítica, mayor o menor) con un criterio de riesgo explícito. Evidencia que debe quedar: Registro del paso.","Indica para cada evento el proceso que lo gestiona y la investigación que exige. Evidencia que debe quedar: Registro del paso.","Señala qué eventos podrían estar relacionados entre sí y por qué. Evidencia que debe quedar: Registro del paso.","Cita la norma o guía que respalda cada decisión. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil.","La discusión de la unidad añade otra capa: En una planta ficticia, los supervisores discuten tres eventos (datos simulados): una pesada que se repitió porque el operario derramó un poco de polvo, con el nuevo peso registrado; un control de dureza fuera de rango que se corrigió ajustando la máquina en el momento; y un retraso de un día en la limpieza de un tanque que no se usó en ese periodo. Unos quieren registrar todo como desviación y otros «solo lo grave». No se trata de opinar: se trata de sostener una postura con una fuente y con los datos del caso."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: tratar todos los riesgos como iguales Corrección: priorizar permite dirigir el esfuerzo a lo que más puede afectar al paciente y al producto.","Error: documentar después de ejecutar Corrección: el registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad.","Error: cerrar una CAPA sin verificar eficacia Corrección: una acción correctiva se cierra cuando se demuestra que el problema no volvió, no cuando se firma el formato.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar referentes internacionales: ICH Q10, OMS, PIC/S y EU GMP en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"]}],"errores":[{"error":"Documentar después de ejecutar","correccion":"El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."},{"error":"Copiar un procedimiento de otra planta","correccion":"El procedimiento debe responder a los equipos, las áreas y los riesgos reales del proceso."},{"error":"Cerrar una CAPA sin verificar eficacia","correccion":"Una acción correctiva se cierra cuando se demuestra que el problema no volvió, no cuando se firma el formato."},{"error":"Tratar todos los riesgos como iguales","correccion":"Priorizar permite dirigir el esfuerzo a lo que más puede afectar al paciente y al producto."},{"error":"Confundir el análisis final con la garantía de calidad","correccion":"El muestreo no detecta todos los defectos; la calidad se construye durante el proceso."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Referentes internacionales: ICH Q10, OMS, PIC/S y EU GMP»?","respuesta":"Compara cómo ICH Q10, el informe técnico de la OMS, la guía PIC/S y el Capítulo 1 de EU GMP tratan las desviaciones y el CAPA."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Matriz de clasificación de eventos con su gestión.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Documentar después de ejecutar El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."}],"resumen":["Referentes internacionales: ICH Q10, OMS, PIC/S y EU GMP se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 1. Fundamentos de las desviaciones y marco regulatorio.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"],"referencias":[{"cita":"Evolución Buenas Prácticas de Manufactura para Medicamentos","url":"https://youtube.com/watch?pp=ygUdI2J1ZW5hc3ByYWN0aWNhc2RlbWFudWZhY3R1cmE%3D&v=qTSJWJDrHwo"},{"cita":"ICH Q10 Pharmaceutical Quality System (sección 3.2.2 Sistema CAPA). ICH (EN)","url":"https://database.ich.org/sites/default/files/Q10%20Guideline.pdf"},{"cita":"[Página web] TRS 986 – Annex 2: WHO good manufacturing practices for pharmaceutical products: Main principles. OMS (EN)","url":"https://www.who.int/publications/m/item/trs986-annex2"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016, manuales de BPM y autoinspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"},{"cita":"PIC/S. PE 009, Guide to Good Manufacturing Practice for Medicinal Products, Part I.","url":"https://picscheme.org/docview/4590"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente referentes internacionales: ICH Q10, OMS, PIC/S y EU GMP en una planta o un laboratorio farmacéutico colombiano.","alt":"Ilustración de referentes internacionales: ICH Q10, OMS, PIC/S y EU GMP"}],"keywords":["curso","gestión","desviaciones","acciones","correctivas","preventivas","referentes","internacionales","unidad","fundamentos","marco","regulatorio"],"mapa":{"centro":"Referentes internacionales: ICH Q10, OMS, PIC/S y EU GMP","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Calidad farmacéutica","Unidad 1. Fundamentos de las desviaciones y marco regulatorio","Requisito"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Documentar después de ejecutar","Copiar un procedimiento de otra planta","Cerrar una CAPA sin verificar eficacia"]}]},"proceso":{"titulo":"Cómo se aplica: Clasificación de diez eventos de calidad","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y escribe una definición operativa de cada tipo de evento.","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Clasifica los diez eventos por tipo (desviación planeada o no planeada, OOS, OOT, queja, no conformidad de auditoría o cambio).","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Asigna a las desviaciones una criticidad (crítica, mayor o menor) con un criterio de riesgo explícito.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Indica para cada evento el proceso que lo gestiona y la investigación que exige.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Señala qué eventos podrían estar relacionados entre sí y por qué.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Cita la norma o guía que respalda cada decisión.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Clasificación de diez eventos de calidad","contexto":"En una semana, Laboratorios Magdalena Medio (ficticio) registró diez eventos (datos simulados): (1) temperatura de una bodega a 28 °C durante 4 horas (límite 25 °C); (2) una valoración de 93 % (especificación 95–105 %); (3) un cliente que encontró una tableta partida; (4) uso planificado de un granulador alterno durante un mantenimiento; (5) un hallazgo de auditoría interna sobre registros incompletos; (6) un aumento de la impureza A en estabilidad, aún dentro de especificación; (7) un cambio de proveedor de cajas aprobado en control de cambios; (8) una etiqueta con el número de lote ilegible en 50 unidades segregadas en línea; (9) un filtro de venteo de un tanque de agua purificada vencido; (10) un operario que entró al área sin cofia.","pregunta":"¿Qué decisión demuestra que entendiste referentes internacionales: ICH Q10, OMS, PIC/S y EU GMP?","opciones":[{"texto":"Verificar el requisito, aplicar el criterio de la clase y documentar la evidencia antes de decidir.","correcta":true,"retro":"La decisión profesional se apoya en el requisito, la evidencia y el registro. Sin esos tres elementos no se puede defender."},{"texto":"Resolver por costumbre o por presión de tiempo, sin revisar la evidencia.","correcta":false,"retro":"La costumbre no reemplaza el criterio. Si no hay evidencia, la decisión queda expuesta."},{"texto":"Trasladar la decisión a otra área sin dejar registro ni seguimiento.","correcta":false,"retro":"Trasladar no es delegar con control: sin registro y seguimiento, el problema vuelve."}]}}$j$::jsonb;
    IF NOT EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
      UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
      INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
      VALUES (v_clase, 'experiencia', 0, v_data);
    ELSE
      UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
       WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    END IF;
    -- Videos arriba, la experiencia debajo y luego el resto.
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
    v_n := v_n + 1;
  END IF;

  -- 07. Introducción a la unidad: las primeras 24 horas de una desviación
  SELECT l.id INTO v_clase
    FROM aula_lessons l
    JOIN aula_modules m ON m.id = l.module_id AND m.deleted_at IS NULL
   WHERE l.course_id = v_curso AND l.deleted_at IS NULL
     AND l.title = $t$Introducción a la unidad: las primeras 24 horas de una desviación$t$
     AND m.title = $u$Unidad 2. Detección, registro, contención y evaluación de impacto$u$
   ORDER BY l.id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase % (unidad %). Se salta.', $t$Introducción a la unidad: las primeras 24 horas de una desviación$t$, $u$Unidad 2. Detección, registro, contención y evaluación de impacto$u$;
  ELSE
    v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"Introducción a la unidad: las primeras 24 horas de una desviación","texto":"En una planta o un laboratorio farmacéutico colombiano, un proveedor cambia de planta y el certificado que llega no cubre la línea que fabrica el insumo. Lo que está en juego es el criterio de introducción a la unidad: las primeras 24 horas de una desviación. Esta clase te da la forma de decidir y la evidencia para sostenerlo."},"objetivos":["Explicar introducción a la unidad: las primeras 24 horas de una desviación con tus propias palabras y reconocer por qué importa en curso de Gestión de Desviaciones y Acciones Correctivas y Preventivas — CAPA.","Relacionar introducción a la unidad: las primeras 24 horas de una desviación con unidad 2. Detección, registro, contención y evaluación de impacto y con las decisiones de el químico farmacéutico de aseguramiento o control de calidad.","Aplicar el criterio de la clase a un caso profesional y justificar la decisión con evidencia.","Identificar el error más frecuente al aplicar introducción a la unidad: las primeras 24 horas de una desviación y la forma de corregirlo."],"conceptos":[{"icono":"Target","termino":"Concepto central","definicion":"Resume las etapas iniciales de la gestión de una desviación: detección, registro, contención y evaluación de impacto."},{"icono":"ShieldCheck","termino":"Requisito","definicion":"Lo que la norma, el registro sanitario o el procedimiento exigen antes de aceptar una decisión. No es una recomendación: es el criterio contra el que se compara la evidencia."},{"icono":"FileCheck","termino":"Evidencia documentada","definicion":"El registro que permite reconstruir qué se hizo, quién lo hizo, cuándo y con qué resultado. Sin evidencia, una actividad existe solo en la memoria de quien la ejecutó."},{"icono":"Network","termino":"Trazabilidad","definicion":"La capacidad de seguir un lote, una muestra o una decisión desde su origen hasta su disposición final. Es lo que permite investigar y responder ante una autoridad."},{"icono":"ClipboardCheck","termino":"Criterio de aceptación","definicion":"El límite definido antes de ejecutar una prueba o una revisión. Si el criterio se fija después de ver el resultado, la decisión pierde valor."},{"icono":"RefreshCw","termino":"Desviación","definicion":"Cualquier apartamiento de lo previsto en un procedimiento, una especificación o una norma. No es solo un error: es una señal que debe evaluarse."}],"secciones":[{"titulo":"Por qué esta clase importa","parrafos":["En una planta o un laboratorio farmacéutico colombiano, introducción a la unidad: las primeras 24 horas de una desviación aparece en medio de una decisión que no admite improvisación: un proveedor cambia de planta y el certificado que llega no cubre la línea que fabrica el insumo. El profesional no necesita recitar la teoría completa, pero sí debe saber qué está protegiendo, qué evidencia tiene y qué haría si algo no cuadra.","Esta clase aísla ese criterio dentro de unidad 2. Detección, registro, contención y evaluación de impacto. El objetivo del curso es claro: Que el Químico Farmacéutico sea capaz de detectar, clasificar, contener e investigar desviaciones, resultados OOS y quejas, y de diseñar, implementar y verificar la efectividad de acciones CAPA conforme a la normativa colombiana y los referentes internacionales. Si la clase se estudia como una lista de definiciones, se pierde la lógica que permite justificar la decisión ante un auditor, un paciente o la autoridad."]},{"titulo":"El contenido esencial","parrafos":["La idea central se puede resumir así: Resume las etapas iniciales de la gestión de una desviación: detección, registro, contención y evaluación de impacto.","Para estudiar esta clase, convierte el título en una pregunta operativa: ¿qué debe estar claro antes de actuar y qué debe quedar registrado después? La respuesta se apoya en requisito y en evidencia documentada, no en la intuición.","La clase pertenece a unidad 2. Detección, registro, contención y evaluación de impacto y se conecta con las demás clases de la unidad. No la estudies aislada: lo que aprendas aquí se usará en el caso de la unidad y en la entrega «Informe inicial de desviación con contención y evaluación de impacto.»."]},{"titulo":"Cómo se aplica en la práctica","parrafos":["Para aplicar introducción a la unidad: las primeras 24 horas de una desviación, sigue un orden que puedas defender. Cada paso deja una evidencia; si no la deja, no se puede reconstruir la decisión.","Lee el caso y redacta la descripción objetiva de la desviación (qué, dónde, cuándo, cómo se detectó). Evidencia que debe quedar: Registro del paso.","Define las acciones de contención antes de las 8:00, incluida la dispensación programada. Evidencia que debe quedar: Registro del paso.","Clasifica las 18 materias primas según su sensibilidad a la temperatura y a la humedad, con base en sus condiciones de almacenamiento. Evidencia que debe quedar: Registro del paso.","Evalúa el impacto para cada grupo y decide qué se libera, qué se analiza y qué se rechaza. Evidencia que debe quedar: Registro del paso.","Clasifica la criticidad de la desviación y define plazos y escalamiento. Evidencia que debe quedar: Registro del paso.","Señala la segunda desviación implícita en el caso y cómo se gestiona. Evidencia que debe quedar: Registro del paso.","Antes de cerrar la clase, pregúntate: ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio? Si no puedes responderlo, vuelve al proceso y revisa el paso que quedó débil."]},{"titulo":"Errores frecuentes y cómo corregirlos","parrafos":["Error: tratar todos los riesgos como iguales Corrección: priorizar permite dirigir el esfuerzo a lo que más puede afectar al paciente y al producto.","Error: copiar un procedimiento de otra planta Corrección: el procedimiento debe responder a los equipos, las áreas y los riesgos reales del proceso.","Error: documentar después de ejecutar Corrección: el registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad.","Un error frecuente es responder solo lo que se preguntó y no lo que el caso necesita. Antes de cerrar, revisa si tu respuesta incluye el requisito, la evidencia, la decisión y el seguimiento. Si falta uno, todavía no está completa."]},{"titulo":"Cierre: lo que debes poder defender","parrafos":["Al terminar deberías poder explicar introducción a la unidad: las primeras 24 horas de una desviación en una frase, aplicarlo a un caso y justificar la decisión con una fuente. Si no puedes hacer las tres cosas, vuelve al caso y a las comprobaciones antes de avanzar. ¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"]}],"errores":[{"error":"Documentar después de ejecutar","correccion":"El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."},{"error":"Copiar un procedimiento de otra planta","correccion":"El procedimiento debe responder a los equipos, las áreas y los riesgos reales del proceso."},{"error":"Cerrar una CAPA sin verificar eficacia","correccion":"Una acción correctiva se cierra cuando se demuestra que el problema no volvió, no cuando se firma el formato."},{"error":"Tratar todos los riesgos como iguales","correccion":"Priorizar permite dirigir el esfuerzo a lo que más puede afectar al paciente y al producto."},{"error":"Confundir el análisis final con la garantía de calidad","correccion":"El muestreo no detecta todos los defectos; la calidad se construye durante el proceso."}],"comprueba":[{"pregunta":"¿Cuál es la idea central de «Introducción a la unidad: las primeras 24 horas de una desviación»?","respuesta":"Resume las etapas iniciales de la gestión de una desviación: detección, registro, contención y evaluación de impacto."},{"pregunta":"¿Qué evidencia demuestra que la clase se aplicó bien?","respuesta":"La entrega de la unidad: Informe inicial de desviación con contención y evaluación de impacto.. Además, el registro de cada paso del proceso y la fuente que sustenta la decisión."},{"pregunta":"¿Qué error conviene evitar y cómo se corrige?","respuesta":"Documentar después de ejecutar El registro se llena en el momento de la actividad; reconstruirlo al final es una falla de integridad."}],"resumen":["Introducción a la unidad: las primeras 24 horas de una desviación se entiende como una decisión profesional, no como un dato aislado.","La unidad la conecta con unidad 2. Detección, registro, contención y evaluación de impacto.","La evidencia y el registro son parte de la respuesta, no un trámite posterior.","¿Qué evidencia llevarías a una auditoría para demostrar que esta decisión se tomó con criterio?"],"referencias":[{"cita":"EudraLex Vol. 4 – Capítulo 1: Pharmaceutical Quality System (desviaciones y CAPA, 1.4 xiv). Comisión Europea (EN)","url":"https://health.ec.europa.eu/system/files/2016-11/vol4-chap1_2013-01_en_0.pdf"},{"cita":"Ministerio de Salud y Protección Social. Resolución 1160 de 2016, manuales de BPM y autoinspección.","url":"https://www.minsalud.gov.co/Normatividad_Nuevo/Resoluci%C3%B3n%201160%20de%202016.pdf"},{"cita":"ICH. Q10: Pharmaceutical Quality System.","url":"https://database.ich.org/sites/default/files/Q10%20Guideline.pdf"},{"cita":"PIC/S. PE 009, Guide to Good Manufacturing Practice for Medicinal Products, Part I.","url":"https://picscheme.org/docview/4590"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Una escena profesional que represente introducción a la unidad: las primeras 24 horas de una desviación en una planta o un laboratorio farmacéutico colombiano.","alt":"Ilustración de introducción a la unidad: las primeras 24 horas de una desviación"}],"keywords":["curso","gestión","desviaciones","acciones","correctivas","preventivas","introducción","unidad","primeras","horas","desviación","detección"],"mapa":{"centro":"Introducción a la unidad: las primeras 24 horas de una desviación","ramas":[{"titulo":"Qué exige el contexto","icono":"Scale","nodos":["Calidad farmacéutica","Unidad 2. Detección, registro, contención y evaluación de impacto","Requisito"]},{"titulo":"Cómo se hace","icono":"Workflow","nodos":["Paso 1","Paso 2","Paso 3"]},{"titulo":"Qué evidencia deja","icono":"FileCheck","nodos":["Registro del paso","Registro del paso","Registro del paso"]},{"titulo":"Dónde falla","icono":"AlertTriangle","nodos":["Documentar después de ejecutar","Copiar un procedimiento de otra planta","Cerrar una CAPA sin verificar eficacia"]}]},"proceso":{"titulo":"Cómo se aplica: Las primeras 24 horas de una desviación","intro":"La clase se aplica con un orden verificable. Cada paso deja una evidencia que permite revisar la decisión.","pasos":[{"titulo":"Paso 1","detalle":"Lee el caso y redacta la descripción objetiva de la desviación (qué, dónde, cuándo, cómo se detectó).","icono":"Search","evidencia":"Registro del paso"},{"titulo":"Paso 2","detalle":"Define las acciones de contención antes de las 8:00, incluida la dispensación programada.","icono":"ClipboardList","evidencia":"Registro del paso"},{"titulo":"Paso 3","detalle":"Clasifica las 18 materias primas según su sensibilidad a la temperatura y a la humedad, con base en sus condiciones de almacenamiento.","icono":"Workflow","evidencia":"Registro del paso"},{"titulo":"Paso 4","detalle":"Evalúa el impacto para cada grupo y decide qué se libera, qué se analiza y qué se rechaza.","icono":"FileCheck","evidencia":"Registro del paso"},{"titulo":"Paso 5","detalle":"Clasifica la criticidad de la desviación y define plazos y escalamiento.","icono":"RefreshCw","evidencia":"Registro del paso"},{"titulo":"Paso 6","detalle":"Señala la segunda desviación implícita en el caso y cómo se gestiona.","icono":"CheckCircle2","evidencia":"Registro del paso"}]},"caso":{"titulo":"Las primeras 24 horas de una desviación","contexto":"El lunes a las 7:00, en Laboratorios Magdalena Medio (ficticio), el registrador de la bodega de materias primas muestra que la temperatura estuvo entre 31 y 33 °C desde el sábado a las 14:00 hasta el lunes a las 6:00 (límite 25 °C) por una falla del aire acondicionado (datos simulados). En la bodega hay 18 materias primas, entre ellas un principio activo termosensible (almacenamiento indicado de 2 a 8 °C, guardado allí por error desde el viernes) y dos excipientes higroscópicos. El lunes a las 8:00 está programada la dispensación de tres lotes.","pregunta":"¿Qué decisión demuestra que entendiste introducción a la unidad: las primeras 24 horas de una desviación?","opciones":[{"texto":"Verificar el requisito, aplicar el criterio de la clase y documentar la evidencia antes de decidir.","correcta":true,"retro":"La decisión profesional se apoya en el requisito, la evidencia y el registro. Sin esos tres elementos no se puede defender."},{"texto":"Resolver por costumbre o por presión de tiempo, sin revisar la evidencia.","correcta":false,"retro":"La costumbre no reemplaza el criterio. Si no hay evidencia, la decisión queda expuesta."},{"texto":"Trasladar la decisión a otra área sin dejar registro ni seguimiento.","correcta":false,"retro":"Trasladar no es delegar con control: sin registro y seguimiento, el problema vuelve."}]}}$j$::jsonb;
